#include <iostream>
#include <vector>
class Buffer {
public:
    std::vector<int> data;
    Buffer& operator=(const Buffer& other) {
        data = other.data; // copy assignment
        return *this;
    }
    Buffer& operator+=(const Buffer& other) {
        data.insert(data.end(), other.data.begin(), other.data.end()); // concatenate
        return *this;
    }
};
int main() {
    Buffer buf1, buf2;
    buf1.data = {1, 2, 3};
    buf2.data = {4, 5, 6};
    buf1 = buf2; // copy assignment
    buf1 += buf2; // compound assignment (concatenate)
    for (int v : buf1.data) {
        std::cout << v << ' ';
    }
    return 0;
}
